(window.__topouhCourseData??=[]).push({"id":"world","title":"Человек и мир","lessons":[{"id":"world-01","title":"Живое и неживое","goal":"Различать живые организмы и объекты неживой природы по признакам, а не по одному движению.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 6, 10, 35","intro":"Во дворе после дождя Ух замечает дерево, облако, камень и улитку под листом.","steps":[{"prompt":"Что в этой истории относится к живой природе?","choices":["Дерево и улитка","Облако и камень","Только улитка"],"answer":0,"feedback":["Они растут и нуждаются в воде.","Ни облако, ни камень не растут как живые организмы.","Дерево тоже живой организм."]},{"prompt":"Улитка замерла. Почему она всё равно живая?","choices":["Она похожа на камень","Она питается и растёт","Она сейчас ползёт"],"answer":1,"feedback":["Внешнее сходство с камнем ничего не говорит о жизни.","Животное не перестаёт жить, когда отдыхает.","В истории улитка не двигается."]},{"prompt":"Ветер катит сухой камешек по наклонной дорожке. Доказывает ли движение, что камешек живой?","choices":["Да, всё движущееся живое","Да, если он движется быстро","Нет, его может сдвинуть внешняя сила"],"answer":2,"feedback":["Неживые вещи тоже меняют положение.","Скорость не показывает, жив ли предмет.","Движение само по себе не признак жизни."]},{"prompt":"Что скорее поможет узнать, живой ли росток?","choices":["Понаблюдать, растут ли новые листья","Сравнить цвет горшка и листа","Проверить, умеет ли росток бегать"],"answer":0,"feedback":["Рост и развитие помогают узнать живое растение.","Цвет горшка не говорит о ростке.","Растение живое, хотя не бегает."]}],"pass":3},{"id":"world-02","title":"Воздух вокруг нас","goal":"Приводить пример, по которому можно заметить движение воздуха.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 11","intro":"На первом рисунке лента флажка свисает вниз. На втором та же лента вытянулась вбок.","steps":[{"prompt":"На каком рисунке легче заметить ветер?","choices":["На первом","На обоих одинаково хорошо","На втором"],"answer":2,"feedback":["Свисающая лента не даёт такой подсказки.","Рисунки показывают разные положения ленты.","Лента вытянулась в сторону под действием ветра."]},{"prompt":"Что двигает ленту в истории?","choices":["Воздух","Цвет флажка","Тень от флажка"],"answer":0,"feedback":["Ветер — это движение воздуха.","Окраска предмета не заставляет его двигаться.","Тень появляется из-за света, она не толкает предметы."]},{"prompt":"Что ещё можно заметить на картинке ветреного двора?","choices":["На скамейке нарисована полоска","Тонкие ветви качаются","Камень отбрасывает тень"],"answer":1,"feedback":["Рисунок на скамейке не связан с ветром.","Ветер способен двигать ветки.","Тень показывает, откуда падает свет."]},{"prompt":"На новом рисунке флажка нет. Какой признак всё равно выдаёт ветер?","choices":["Дорожка серая","На клумбе три цветка","Сухие листья летят в одну сторону"],"answer":2,"feedback":["Цвет асфальта не меняется из-за ветра.","Число цветков не показывает движение воздуха.","Летящие листья показывают движение воздуха."]}],"pass":3},{"id":"world-03","title":"Где есть вода","goal":"Находить воду в знакомых ситуациях и объяснять, зачем она нужна живому.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 19","intro":"После дождя в парке блестят лужа и капли на траве. Садовница поливает цветы.","steps":[{"prompt":"Где в истории есть вода?","choices":["Только на дорожке","В луже и в каплях на траве","В сухой скамейке и в табличке"],"answer":1,"feedback":["Вода осталась также на траве.","И лужа, и капли образовались из дождевой воды.","Эти предметы не названы местами с водой."]},{"prompt":"Зачем садовница поливает цветы?","choices":["Чтобы лепестки стали деревянными","Чтобы растения могли ходить","Чтобы растения получали нужную им воду"],"answer":2,"feedback":["Вода помогает цветку расти, а не меняет его в дерево.","Растения не ходят после полива.","Растениям нужна вода для жизни и роста."]},{"prompt":"Почему в истории после дождя на дорожке появилась лужа?","choices":["Вода собралась в углублении","Дорожка сделала воду из камня","Травинки выжали воду из воздуха"],"answer":0,"feedback":["Дождевая вода может собираться в низких местах.","Камень не превращается в дождевую воду.","Капли на траве не объясняют всю лужу."]},{"prompt":"У вымышленного кролика есть сено, укрытие и пустая миска. Чего не хватает?","choices":["Второго пустого укрытия","Доступа к питьевой воде","Нарисованной лужи"],"answer":1,"feedback":["Укрытие уже есть, а воды нет.","Как и растениям, животным нужна вода.","Рисунок не может заменить настоящую воду."]}],"pass":3},{"id":"world-04","title":"Почва и растение","goal":"Показывать, где находятся корни и почему почва важна для многих растений.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 27, 36","intro":"На схеме клумбы под коричневым слоем ветвятся корни. Над ним видны стебель и листья.","steps":[{"prompt":"Какая часть на схеме спрятана в почве?","choices":["Корни","Листья","Верхушка стебля"],"answer":0,"feedback":["Их веточки на рисунке находятся под поверхностью.","На схеме листья находятся над почвой.","Верхушка показана над землёй."]},{"prompt":"Что корни получают из влажной почвы?","choices":["Солнечный свет","Воду","Готовые листья"],"answer":1,"feedback":["Свет получает надземная часть растения.","Вода из почвы поступает к растению через корни.","Листья вырастают из самого растения."]},{"prompt":"Какую роль почва играет, кроме запаса воды?","choices":["Она переносит растение с места на место","Она заменяет листья","Она помогает корням удерживать растение"],"answer":2,"feedback":["Закрепившиеся корни обычно удерживают его на одном месте.","Листья выполняют свои задачи и не заменяются почвой.","Корни закрепляются в почве."]},{"prompt":"На схеме фасоли слева подписи потерялись. Как узнать корни?","choices":["Найти разветвления, уходящие от стебля в почву","Выбрать самую верхнюю пару листьев","Выбрать подпись на краю рисунка"],"answer":0,"feedback":["Место и форма помогают узнать корни.","Листья видны над землёй.","Положение подписи ничего не говорит о части растения."]}],"pass":3},{"id":"world-05","title":"Растения, грибы и животные","goal":"Различать три группы на примерах без вывода о пригодности грибов в пищу.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 35–36, 73, 76","intro":"Ух рисует для выставки берёзу, ежа и лесной гриб. Рисунки нужны, чтобы различать группы живого.","steps":[{"prompt":"В какую группу попадает берёза?","choices":["Животные","Грибы","Растения"],"answer":2,"feedback":["Берёза не животное, хотя она тоже живая.","Листья и ствол здесь принадлежат дереву.","Берёза — дерево, а деревья относятся к растениям."]},{"prompt":"К какой группе относится ёж?","choices":["Животные","Растения","Грибы"],"answer":0,"feedback":["Ёж питается, растёт и передвигается как животное.","Колючки сами по себе не делают ежа растением.","Ёж не гриб, даже если они оба встречаются в лесу."]},{"prompt":"Что написать на третьей карточке выставки?","choices":["Растения","Грибы","Животные"],"answer":1,"feedback":["Грибы не растения, даже если растут рядом с ними.","Лесной гриб относится к особой группе живого.","Грибы не относятся к животным."]},{"prompt":"Можно ли по рисунку решить, что похожий гриб в лесу можно есть?","choices":["Да, если совпадает цвет","Да, если гриб небольшой","Нет, по рисунку этого не определяют"],"answer":2,"feedback":["Похожие по цвету грибы могут быть очень разными.","Размер не показывает, съедобен ли гриб.","Незнакомые грибы не трогают и не пробуют; о находке можно сказать взрослому."]}],"pass":3},{"id":"world-06","title":"Как животные живут в природе","goal":"Сопоставлять знакомое животное с подходящей для него средой.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 76","intro":"Редактор рисованной энциклопедии подбирает места для щуки, белки и полевой мыши.","steps":[{"prompt":"Какая сцена подходит щуке?","choices":["Ветка сосны","Пресный водоём","Сухая нора в поле"],"answer":1,"feedback":["Щука не живёт на дереве.","Щука живёт в воде и дышит жабрами.","В сухой норе щука не может жить."]},{"prompt":"Что на рисунке леса может помочь белке найти пищу?","choices":["Каменная табличка","Гладкая лужа на дорожке","Шишки на дереве"],"answer":2,"feedback":["Табличка не даёт белке еды.","В этой подсказке речь о пище, а не о воде.","Белка может питаться семенами из шишек."]},{"prompt":"Где на рисунке поля мышь может укрыться?","choices":["В норе","На открытой верхушке флагштока","В глубокой воде"],"answer":0,"feedback":["Нора служит мыши укрытием.","На высоком открытом месте нет подходящего укрытия.","Полевая мышь не прячется в глубокой воде."]},{"prompt":"На другой странице нарисована лягушка. Какая деталь лучше подходит к рассказу о её среде?","choices":["Сухой подоконник без воды","Берег пруда с водными растениями","Пустая дорожная коробка"],"answer":1,"feedback":["Такое место не похоже на среду у водоёма.","Вода и укрытия около берега подходят многим лягушкам.","В коробке нет нужных условий для жизни лягушки."]}],"pass":3},{"id":"world-07","title":"Забота о здоровье","goal":"Собирать разумную цепочку повседневных привычек без оценивания ребёнка или семьи.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 114, 118, 123","intro":"В истории про обед персонаж закончил рисовать, а взрослый позвал к столу.","steps":[{"prompt":"Что лучше сделать перед едой?","choices":["Вымыть руки","Подвинуть чашку карандашом","Подождать окончания обеда"],"answer":0,"feedback":["Чистые руки помогают не переносить грязь на еду.","Это не делает руки чистыми.","Руки полезно вымыть до того, как берёшь еду."]},{"prompt":"Какой порядок подходит истории?","choices":["Поесть, вымыть руки, снова накрыть к обеду","Вымыть руки, поесть, убрать за собой","Убрать за собой, а потом начать обед"],"answer":1,"feedback":["Так мытьё рук не происходит перед едой.","Мытьё рук предшествует еде, а уборка завершает обед.","Уборка своего места обычно завершает обед."]},{"prompt":"Какой вымышленный обед показывает разнообразие еды?","choices":["Три порции одной и той же каши","Один сорт яблока в трёх тарелках","Гречка, фасоль и нарезанные овощи"],"answer":2,"feedback":["Количество порций не делает еду разнообразной.","Это один и тот же продукт.","Здесь есть продукты из разных групп."]},{"prompt":"После прогулки герои собираются на перекус. Какое правило переносится из истории про обед?","choices":["Сначала вымыть руки","Сначала спрятать салфетки","Мыть руки только после рисования"],"answer":0,"feedback":["Это полезно перед перекусом так же, как перед обедом.","Салфетки не заменяют чистые руки.","Полезная привычка нужна не только после рисования."]}],"pass":3},{"id":"world-08","title":"Семья, правила и права","goal":"Различать право ребёнка и посильный способ заботиться о других.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 128–132","intro":"В придуманной семье один герой устал после занятий, другой собирает игрушки перед ужином.","steps":[{"prompt":"Что из этого относится к праву ребёнка?","choices":["Побеждать в каждой игре","Заставлять другого играть","Отдыхать и играть"],"answer":2,"feedback":["Право на игру не означает гарантированной победы.","Уважать отдых важно у каждого.","Право на отдых есть у каждого ребёнка."]},{"prompt":"Как можно посильно помочь близким?","choices":["Убрать собственные игрушки","Выполнить все дела за взрослых","Переложить свои вещи на чужое место"],"answer":0,"feedback":["Это небольшое дело, с которым герой может справиться.","Помощь не обязана быть большой или непосильной.","Это создаёт новую работу другим."]},{"prompt":"Герой устал, а игрушки ещё на полу. Какая просьба уважает обоих?","choices":["«Ты не имеешь права отдыхать»","«Давай отдохнём, потом вместе уберём игрушки»","«Мои вещи всегда убираешь ты»"],"answer":1,"feedback":["Уставшему герою нужно время на отдых.","Здесь есть время на отдых и участие в общем деле.","Это перекладывает свою посильную работу на другого."]},{"prompt":"В новой истории герои выбирают, как играть вместе. Что согласуется с уважением к другим?","choices":["Продолжать настаивать, если он отказался","Спрятать его игрушку, чтобы он согласился","Спросить, хочет ли другой герой играть сейчас"],"answer":2,"feedback":["Отказ и право на отдых важно уважать.","Это мешает свободному выбору.","У другого героя тоже есть выбор и право отдохнуть."]}],"pass":3},{"id":"world-09","title":"Откуда берутся вещи","goal":"Связывать знакомую вещь с несколькими видами труда.","source":"Г. В. Трафимова, С. А. Трафимов. «Человек и мир». 2 класс, 2024. с. 136, 139","intro":"На выставке сделали четыре карточки об обычной тетради: бумага, изготовление, доставка, книжный магазин.","steps":[{"prompt":"Какая карточка обозначает материал тетради?","choices":["Доставка","Бумага","Книжный магазин"],"answer":1,"feedback":["Это этап перемещения, не материал.","Из неё делают листы.","Там тетрадь можно купить, но это не материал."]},{"prompt":"Что происходит прежде, чем готовую тетрадь доставят?","choices":["Её уже продаёт магазин","Покупатель начинает в ней писать","Из бумаги изготавливают тетрадь"],"answer":2,"feedback":["Магазин сначала должен получить тетрадь.","Писать в неё можно уже после получения.","Сначала появляется готовый предмет, потом его везут."]},{"prompt":"Какой порядок подходит всем четырём карточкам?","choices":["Бумага → изготовление → доставка → магазин","Магазин → доставка → бумага → изготовление","Доставка → изготовление → магазин → бумага"],"answer":0,"feedback":["Так показаны материал, работа и путь готовой вещи.","В магазин тетрадь попадает после изготовления и доставки.","Сначала нужен материал, а доставляют уже готовую вещь."]},{"prompt":"Из мастерской в магазин везут деревянную игрушку. Как называют этот этап?","choices":["Изготовление","Доставка","Выбор материала"],"answer":1,"feedback":["Игрушку уже сделали в мастерской.","Перевозка готового предмета — доставка.","Материал выбирают до изготовления, а не во время перевозки."]}],"pass":3},{"id":"world-10","module":"Закрепление","title":"Следы живого","goal":"Узнавать признаки живого по наблюдениям.","intro":"Ни один признак сам по себе не решает всё. Ветер двигает листья, но сам ветер не растёт.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что помогает понять, что маленький клён живой?","choices":["По стволу скатилась капля","На ветке выросли новые листья","Тень от клёна стала длиннее"],"answer":1,"feedback":["Этот вариант не подходит: «по стволу скатилась капля». Ещё раз посмотри на условие.","Рост новых листьев показывает, что дерево развивается.","Этот вариант не подходит: «тень от клёна стала длиннее». Проверь, относится ли выбор к ситуации."]},{"prompt":"Какой объект живой, хотя на рисунке он неподвижен?","choices":["Пустая ракушка на песке","Камень у дорожки","Улитка в раковине"],"answer":2,"feedback":["Этот вариант не подходит: «пустая ракушка на песке». Ещё раз посмотри на условие.","Этот вариант не подходит: «камень у дорожки». Сравни последствия трёх вариантов.","Улитка может спрятаться и не двигаться, но она живая."]},{"prompt":"Почему лужа не становится живой, когда её поверхность дрожит?","choices":["Лужа слишком маленькая","Рябь вызвал ветер","Вода не занимает места"],"answer":1,"feedback":["Этот вариант не подходит: «лужа слишком маленькая». Сравни последствия трёх вариантов.","Движение поверхности вызвано воздухом и не означает, что лужа живая.","Этот вариант не подходит: «вода не занимает места». Найди объяснение, которое подходит к рисунку."]},{"prompt":"На двух снимках через неделю у мха появились новые участки. Что это показывает?","choices":["Камень под ним тоже рос","Мох рос","Любая зелёная вещь живая"],"answer":1,"feedback":["Этот вариант не подходит: «камень под ним тоже рос». Найди объяснение, которое подходит к рисунку.","Новые участки мха помогают заметить рост.","Этот вариант не подходит: «любая зелёная вещь живая». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"world-11","module":"Закрепление","title":"Движение воздуха","goal":"Замечать ветер по изменениям окружающих предметов.","intro":"Сам воздух обычно не виден. Зато можно сравнить, что происходит с лёгкими предметами.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Какой признак заметнее всего при ветре?","choices":["У забора лежит кирпич","Веточки качаются в одной стороне двора","На стволе нарисована метка"],"answer":1,"feedback":["Этот вариант не подходит: «у забора лежит кирпич». Сравни последствия трёх вариантов.","Ветер может раскачивать тонкие веточки.","Этот вариант не подходит: «на стволе нарисована метка». Ещё раз посмотри на условие."]},{"prompt":"Что видно на двух кадрах, если лист понесло ветром?","choices":["От листа не осталось тени","Лист внезапно стал тяжелее кирпича","Лёгкий лист переместился с места на место"],"answer":2,"feedback":["Этот вариант не подходит: «от листа не осталось тени». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «лист внезапно стал тяжелее кирпича». Сравни последствия трёх вариантов.","Сравнение положения листа позволяет заметить движение воздуха."]},{"prompt":"На тихой улице бумажные полоски висят прямо, на мосту отклоняются. Чем отличаются места на снимках?","choices":["На мосту бумага стала другим материалом","Полоски растут быстрее рядом с водой","На мосту полоски отклоняются от движения воздуха"],"answer":2,"feedback":["Этот вариант не подходит: «на мосту бумага стала другим материалом». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «полоски растут быстрее рядом с водой». Проверь, относится ли выбор к ситуации.","Воздух действует на лёгкие полоски там, где они отклоняются."]},{"prompt":"Какой предмет лучше всего покажет ветер из окна?","choices":["Лёгкая лента, привязанная на улице","Кирпич на земле","Фотография ленты на стене"],"answer":0,"feedback":["Лёгкая свободная часть ленты меняет положение.","Этот вариант не подходит: «кирпич на земле». Ещё раз посмотри на условие.","Этот вариант не подходит: «фотография ленты на стене». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"world-12","module":"Закрепление","title":"Куда исчезла лужа","goal":"Различать наблюдаемое изменение воды и его объяснение.","intro":"Вода может оставаться заметной каплями или постепенно переходить в воздух.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Лужа утром большая, а днём стала меньше. Что заметил ребёнок?","choices":["В той части двора выпал снег","Занятая водой площадь уменьшилась","Камни вокруг лужи выросли"],"answer":1,"feedback":["Этот вариант не подходит: «в той части двора выпал снег». Сравни последствия трёх вариантов.","По размерам лужи на двух снимках видно, что воды на поверхности стало меньше.","Этот вариант не подходит: «камни вокруг лужи выросли». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Что можно увидеть после дождя?","choices":["Ветер внутри листа","Капли на листе","Песок внутри облака"],"answer":1,"feedback":["Этот вариант не подходит: «ветер внутри листа». Найди объяснение, которое подходит к рисунку.","Капли на поверхности листа видны сразу.","Этот вариант не подходит: «песок внутри облака». Проверь, относится ли выбор к ситуации."]},{"prompt":"В обычной комнате мокрое полотенце со временем подсохло. Что произошло с частью воды?","choices":["Превратилась в ткань","Стала тенью полотенца","Перешла в воздух при испарении"],"answer":2,"feedback":["Этот вариант не подходит: «превратилась в ткань». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «стала тенью полотенца». Ещё раз посмотри на условие.","При высыхании часть воды переходит в воздух."]},{"prompt":"На каком рисунке есть вода именно в виде отдельных капель?","choices":["На стекле видны круглые следы дождя","На земле лежит плоский камешек","На сухой стене нарисован круг"],"answer":0,"feedback":["Отдельные капли дождя заметны на стекле.","Этот вариант не подходит: «на земле лежит плоский камешек». Сравни последствия трёх вариантов.","Этот вариант не подходит: «на сухой стене нарисован круг». Ещё раз посмотри на условие."]}],"pass":2},{"id":"world-13","module":"Закрепление","title":"Что видно под землёй","goal":"Различать надземные и подземные части растения.","intro":"На схеме можно показать то, что обычно закрыто слоем почвы.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Какая часть одуванчика обычно находится под землёй?","choices":["Лист на стебле","Цветок","Корень"],"answer":2,"feedback":["Этот вариант не подходит: «лист на стебле». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «цветок». Найди объяснение, которое подходит к рисунку.","Корень находится в почве и помогает удерживать растение."]},{"prompt":"Чем корни обычного зелёного растения пользуются из влажной почвы?","choices":["Водой","Солнечными зайчиками","Дорожной разметкой"],"answer":0,"feedback":["Корни многих растений впитывают воду из почвы.","Этот вариант не подходит: «солнечными зайчиками». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «дорожной разметкой». Ещё раз посмотри на условие."]},{"prompt":"На схеме луковица посажена, а тонкие корешки направлены вверх. Что исправить?","choices":["Показать корешки растущими в почву","Перекрасить землю в голубой","Добавить ещё один цветок сверху"],"answer":0,"feedback":["Корешки на схеме должны находиться там, где растение получает воду и закрепляется.","Этот вариант не подходит: «перекрасить землю в голубой». Ещё раз посмотри на условие.","Этот вариант не подходит: «добавить ещё один цветок сверху». Сравни последствия трёх вариантов."]},{"prompt":"Почему высокому стеблю помогают корни?","choices":["Они красят цветок","Они заменяют листья","Они удерживают растение в почве"],"answer":2,"feedback":["Этот вариант не подходит: «они красят цветок». Сравни последствия трёх вариантов.","Этот вариант не подходит: «они заменяют листья». Найди объяснение, которое подходит к рисунку.","Корни служат опорой, а не заменяют другие органы."]}],"pass":2},{"id":"world-14","module":"Закрепление","title":"Узнай группу","goal":"Относить знакомые организмы к растениям, животным или грибам.","intro":"Сравнивайте известные рисунки, не решая, какие грибы или ягоды пригодны в пищу.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что из списка — гриб?","choices":["Нарисованная синица","Нарисованный мухомор","Нарисованная берёза"],"answer":1,"feedback":["Этот вариант не подходит: «нарисованная синица». Ещё раз посмотри на условие.","Мухомор относится к грибам; рисунок не даёт разрешения прикасаться к нему.","Этот вариант не подходит: «нарисованная берёза». Проверь, относится ли выбор к ситуации."]},{"prompt":"Что из списка относится к растениям?","choices":["Улитка","Ель","Муравей"],"answer":1,"feedback":["Этот вариант не подходит: «улитка». Сравни последствия трёх вариантов.","Ель — растение, даже если она выше большинства других растений рядом.","Этот вариант не подходит: «муравей». Ещё раз посмотри на условие."]},{"prompt":"Какие два рисунка показывают животных?","choices":["Бабочка и улитка","Папоротник и бабочка","Берёза и подосиновик"],"answer":0,"feedback":["Бабочка и улитка относятся к животным, хотя выглядят по-разному.","Этот вариант не подходит: «папоротник и бабочка». Сравни последствия трёх вариантов.","Этот вариант не подходит: «берёза и подосиновик». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Под деревом вырос неизвестный гриб. Можно ли решить по похожему рисунку, что он съедобен?","choices":["Да, если шляпка похожа по цвету","Да, если гриб небольшого размера","Нет, не брать его и обратиться к взрослому"],"answer":2,"feedback":["Этот вариант не подходит: «да, если шляпка похожа по цвету». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «да, если гриб небольшого размера». Проверь, относится ли выбор к ситуации.","Цвет и размер не позволяют безопасно судить о неизвестном грибе."]}],"pass":2},{"id":"world-15","module":"Закрепление","title":"Где животному удобно","goal":"Связывать особенности известных животных с функциями.","intro":"У каждого примера ищем наблюдаемую подсказку: лапы, крылья, след или укрытие.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что помогает утке грести по воде?","choices":["Перепонки между пальцами","Длинная тень","Цвет неба"],"answer":0,"feedback":["Перепончатые лапы помогают отталкивать воду.","Этот вариант не подходит: «длинная тень». Сравни последствия трёх вариантов.","Этот вариант не подходит: «цвет неба». Ещё раз посмотри на условие."]},{"prompt":"Как белке удобно перемещаться по ветвям?","choices":["Цепляться лапами за кору и ветки","Собирать крылья под панцирем","Толкать воду плавниками"],"answer":0,"feedback":["Лапы помогают белке удерживаться на ветках.","Этот вариант не подходит: «собирать крылья под панцирем». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «толкать воду плавниками». Сравни последствия трёх вариантов."]},{"prompt":"Что именно в пруду подходит головастику?","choices":["Каменная стена вдали от воды","Высокая сухая ветка","Место для движения в воде"],"answer":2,"feedback":["Этот вариант не подходит: «каменная стена вдали от воды». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «высокая сухая ветка». Найди объяснение, которое подходит к рисунку.","Головастик живёт и движется в воде."]},{"prompt":"Чем спины птицы и рыбы не объясняют, где им удобно двигаться?","choices":["Одного цвета спины недостаточно; важны крылья или плавники","Чем темнее спина, тем выше полёт","Любая окраска помогает одинаково плавать и летать"],"answer":0,"feedback":["Сравнение частей тела даёт более полезную подсказку, чем один оттенок.","Этот вариант не подходит: «чем темнее спина, тем выше полёт». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «любая окраска помогает одинаково плавать и летать». Ещё раз посмотри на условие."]}],"pass":2},{"id":"world-16","module":"Закрепление","title":"Забота о себе по порядку","goal":"Выстраивать цепочки простых здоровых привычек.","intro":"Привычки удобнее привязывать к обычным событиям: прогулке, еде, отдыху.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что логично сделать после игры на улице, прежде чем сесть за стол?","choices":["Сразу взять еду","Вымыть руки","Отложить мытьё до завтра"],"answer":1,"feedback":["Этот вариант не подходит: «сразу взять еду». Сравни последствия трёх вариантов.","После улицы руки моют до еды.","Этот вариант не подходит: «отложить мытьё до завтра». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Что помогает разнообразить условный обед?","choices":["Выбирать разные продукты, а не только любимое лакомство","Каждый раз выбирать только сладость","Полностью заменять обед сладким напитком"],"answer":0,"feedback":["Разнообразие не означает исключение всех любимых продуктов.","Этот вариант не подходит: «каждый раз выбирать только сладость». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «полностью заменять обед сладким напитком». Проверь, относится ли выбор к ситуации."]},{"prompt":"В школьной истории после долгой работы глаза устали. Что разумнее выбрать?","choices":["Ускориться и вовсе не останавливаться","Сделать короткую паузу по договорённости с учителем","Поднести экран ближе к лицу"],"answer":1,"feedback":["Этот вариант не подходит: «ускориться и вовсе не останавливаться». Проверь, относится ли выбор к ситуации.","Пауза помогает отдохнуть, не заставляя терпеть усталость.","Этот вариант не подходит: «поднести экран ближе к лицу». Ещё раз посмотри на условие."]},{"prompt":"Ребёнок заметил грязь на руках уже за столом. Что сделать?","choices":["Продолжать и не обращать внимания","Попросить минуту, чтобы вымыть руки","Вытереть руки об учебник"],"answer":1,"feedback":["Этот вариант не подходит: «продолжать и не обращать внимания». Сравни последствия трёх вариантов.","Мыть руки можно и после того, как заметил, что забыл об этом.","Этот вариант не подходит: «вытереть руки об учебник». Ещё раз посмотри на условие."]}],"pass":2},{"id":"world-17","module":"Закрепление","title":"Права и помощь близким","goal":"Различать право ребёнка и доброжелательную помощь.","intro":"Ситуации вымышлены: не нужно показывать свои семейные дела или документы.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что иллюстрирует право ребёнка на отдых?","choices":["После занятий остаётся время поиграть или отдохнуть","Ребёнок должен разбирать чужие сумки","Взрослый выбирает все игры за ребёнка"],"answer":0,"feedback":["Время для полноценного отдыха важно независимо от поручений.","Этот вариант не подходит: «ребёнок должен разбирать чужие сумки». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «взрослый выбирает все игры за ребёнка». Проверь, относится ли выбор к ситуации."]},{"prompt":"Какое дело показывает посильную помощь?","choices":["Самостоятельно чинить провод","Сложить свои карандаши после рисования","Решить за всех, кому запрещено отдыхать"],"answer":1,"feedback":["Этот вариант не подходит: «самостоятельно чинить провод». Проверь, относится ли выбор к ситуации.","Навести порядок в своих материалах — посильный вклад.","Этот вариант не подходит: «решить за всех, кому запрещено отдыхать». Ещё раз посмотри на условие."]},{"prompt":"Двум детям нужны одни и те же фломастеры в общем наборе. Как учесть интересы обоих?","choices":["Договориться о порядке и поделиться","Обвинить второго ребёнка в том, что он попросил","Спрятать всё у себя"],"answer":0,"feedback":["Договор позволяет обоим воспользоваться общим набором.","Этот вариант не подходит: «обвинить второго ребёнка в том, что он попросил». Сравни последствия трёх вариантов.","Этот вариант не подходит: «спрятать всё у себя». Ещё раз посмотри на условие."]},{"prompt":"Ребёнок устал и ему предлагают помощь с тяжёлой вещью. Что можно сделать?","choices":["Поднимать вещь любой ценой","Не говорить о сложностях","Сказать, что нужна помощь взрослого"],"answer":2,"feedback":["Этот вариант не подходит: «поднимать вещь любой ценой». Сравни последствия трёх вариантов.","Этот вариант не подходит: «не говорить о сложностях». Найди объяснение, которое подходит к рисунку.","Можно спокойно сообщить, что дело оказалось непосильным."]}],"pass":2},{"id":"world-18","module":"Закрепление","title":"Путь знакомой вещи","goal":"Восстанавливать простую цепочку изготовления и доставки.","intro":"У разных вещей разные материалы, но почти всегда можно найти, кто их делает и как они приходят к людям.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что нужно мастерской до изготовления деревянной линейки?","choices":["Цена в магазине","Подходящая древесина","Домашнее задание покупателя"],"answer":1,"feedback":["Этот вариант не подходит: «цена в магазине». Проверь, относится ли выбор к ситуации.","Материал нужен раньше, чем появится готовая вещь.","Этот вариант не подходит: «домашнее задание покупателя». Ещё раз посмотри на условие."]},{"prompt":"Что может произойти после упаковки партии тетрадей?","choices":["Бумага вернётся в виде дерева","Из тетради вынут все страницы","Их доставят в магазин"],"answer":2,"feedback":["Этот вариант не подходит: «бумага вернётся в виде дерева». Ещё раз посмотри на условие.","Этот вариант не подходит: «из тетради вынут все страницы». Сравни последствия трёх вариантов.","Готовые тетради обычно перевозят к месту продажи."]},{"prompt":"Какой порядок разумен для хлеба в условной схеме?","choices":["Получить муку → испечь хлеб → посадить зерно для этого урожая","Испечь хлеб → собрать зерно → получить муку","Вырастить зерно → получить муку → испечь хлеб"],"answer":2,"feedback":["Этот вариант не подходит: «получить муку → испечь хлеб → посадить зерно для этого урожая». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «испечь хлеб → собрать зерно → получить муку». Сравни последствия трёх вариантов.","Сначала получают зерно, затем продукты его переработки."]},{"prompt":"Что означает «в магазине закончились готовые тетради»?","choices":["Никто больше не умеет делать бумагу","Купить тетрадь можно только в прошлом году","Может понадобиться новая поставка"],"answer":2,"feedback":["Этот вариант не подходит: «никто больше не умеет делать бумагу». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «купить тетрадь можно только в прошлом году». Найди объяснение, которое подходит к рисунку.","Отсутствие товара в одном магазине не означает исчезновение материала или труда."]}],"pass":2},{"id":"world-19","module":"Применение","title":"Двор как маленькая карта","goal":"Применять признаки живого к объектам на условной карте.","intro":"Карта показывает места, а карточки помогают отметить, где наблюдается рост или питание.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Что живое следует отметить на схеме двора?","choices":["Скамейку под ней","Рябину у дорожки","Плитку дорожки"],"answer":1,"feedback":["Этот вариант не подходит: «скамейку под ней». Ещё раз посмотри на условие.","Рябина — растение; расположение на карте не меняет её признаки.","Этот вариант не подходит: «плитку дорожки». Сравни последствия трёх вариантов."]},{"prompt":"Что можно добавить на отдельный слой неживых объектов?","choices":["Лужу после дождя","Синицу в кусте","Мох около камня"],"answer":0,"feedback":["Отдельный слой помогает видеть неживые объекты.","Этот вариант не подходит: «синицу в кусте». Сравни последствия трёх вариантов.","Этот вариант не подходит: «мох около камня». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Два рисунка двора сделаны в разные дни. На каком примере можно обсудить развитие живого?","choices":["Камешек перекатился","У стены стала другой тень","На ветке распустились почки"],"answer":2,"feedback":["Этот вариант не подходит: «камешек перекатился». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «у стены стала другой тень». Найди объяснение, которое подходит к рисунку.","Распускание почек связано с развитием растения."]},{"prompt":"Как лучше отметить автобус на карте, если группы «природные живые», «природные неживые» и «сделанные человеком» раздельны?","choices":["Отнести его к неживой природе, ведь он металлический","Отнести автобус к сделанным человеком","Отнести его к живому, ведь он движется"],"answer":1,"feedback":["Этот вариант не подходит: «отнести его к неживой природе, ведь он металлический». Ещё раз посмотри на условие.","В трёхчастной схеме для транспорта подходит отдельная группа созданных человеком предметов.","Этот вариант не подходит: «отнести его к живому, ведь он движется». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"world-20","module":"Применение","title":"Погода по картинкам","goal":"Сравнивать наблюдения и выбирать верное описание.","intro":"Дневник наблюдений помогает отличить то, что видно, от догадки.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"В кадре мокрые стёкла и облака. Что точно видно?","choices":["На стекле есть следы воды","На улице сильный мороз","Завтра тоже обязательно будет дождь"],"answer":0,"feedback":["Следы воды видны; будущую погоду по этому кадру не определить.","Этот вариант не подходит: «на улице сильный мороз». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «завтра тоже обязательно будет дождь». Сравни последствия трёх вариантов."]},{"prompt":"Какой предмет в рисунке подтверждает движение воздуха?","choices":["Развевающийся флажок","Значок солнца на табличке","Закрытая коробка"],"answer":0,"feedback":["Положение флажка может показать движение воздуха.","Этот вариант не подходит: «значок солнца на табличке». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «закрытая коробка». Проверь, относится ли выбор к ситуации."]},{"prompt":"В первом кадре капель на окне нет, во втором они уже видны. Какая запись точнее?","choices":["Вода умеет подниматься только вверх","Воздух исчез из комнаты","На стекле появились капли"],"answer":2,"feedback":["Этот вариант не подходит: «вода умеет подниматься только вверх». Ещё раз посмотри на условие.","Этот вариант не подходит: «воздух исчез из комнаты». Проверь, относится ли выбор к ситуации.","Запись сообщает именно наблюдаемое изменение."]},{"prompt":"На двух фотографиях одинаковые кусты сильно наклонены только на второй. Что лучше написать?","choices":["Деревья за минуту перестали быть живыми","На втором снимке видны отклонённые ветки","Я знаю точную скорость ветра по одному кадру"],"answer":1,"feedback":["Этот вариант не подходит: «деревья за минуту перестали быть живыми». Ещё раз посмотри на условие.","Положение веток видно; точную скорость рисунок не показывает.","Этот вариант не подходит: «я знаю точную скорость ветра по одному кадру». Сравни последствия трёх вариантов."]}],"pass":2},{"id":"world-21","module":"Применение","title":"Вода в одном дне","goal":"Объяснять роль воды в разных знакомых ситуациях.","intro":"Человек и другие живые организмы нуждаются в воде, но чистота и подходящий способ использования тоже важны.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Для чего на рисунке поливают комнатное растение?","choices":["Чтобы вымыть книжку","Чтобы дать растению воду","Чтобы привлечь тень"],"answer":1,"feedback":["Этот вариант не подходит: «чтобы вымыть книжку». Найди объяснение, которое подходит к рисунку.","Полив даёт воду почве, затем её получают корни.","Этот вариант не подходит: «чтобы привлечь тень». Проверь, относится ли выбор к ситуации."]},{"prompt":"Как изобразить заботу о воде без реальных действий?","choices":["Нарисовать кран, открытый без причины","Нарисовать, что воды на Земле нет","Выбрать на схеме закрытый кран, когда вода не нужна"],"answer":2,"feedback":["Этот вариант не подходит: «нарисовать кран, открытый без причины». Ещё раз посмотри на условие.","Этот вариант не подходит: «нарисовать, что воды на Земле нет». Проверь, относится ли выбор к ситуации.","Картинка может показать, что воду используют по делу."]},{"prompt":"Почему животные подходят пить в подходящих для них местах?","choices":["Вода превращает животное в растение","Пить им нужно только ради шума","Вода нужна организму животного"],"answer":2,"feedback":["Этот вариант не подходит: «вода превращает животное в растение». Ещё раз посмотри на условие.","Этот вариант не подходит: «пить им нужно только ради шума». Сравни последствия трёх вариантов.","Вода нужна живым организмам."]},{"prompt":"В карточках нужно различить «вода для полива» и «вода для питья». Что пояснить?","choices":["Видимая прозрачность всегда означает безопасность","Для питья нужна вода, безопасность которой подтвердили взрослые","Всю воду из лейки можно пить"],"answer":1,"feedback":["Этот вариант не подходит: «видимая прозрачность всегда означает безопасность». Найди объяснение, которое подходит к рисунку.","Внешний вид не позволяет узнать, подходит ли вода для питья.","Этот вариант не подходит: «всю воду из лейки можно пить». Сравни последствия трёх вариантов."]}],"pass":2},{"id":"world-22","module":"Применение","title":"Растение на схеме сада","goal":"Использовать схему растения для объяснения ролей частей.","intro":"На условном рисунке удобно перемещать ярлыки, не трогая настоящие растения.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Куда поставить ярлык «стебель»?","choices":["На камень около растения","На тень между грядками","На часть, поддерживающую листья над почвой"],"answer":2,"feedback":["Этот вариант не подходит: «на камень около растения». Ещё раз посмотри на условие.","Этот вариант не подходит: «на тень между грядками». Проверь, относится ли выбор к ситуации.","Стебель — часть самого растения, удерживающая листья."]},{"prompt":"Что показывает стрелка «вода из почвы»?","choices":["Направление от стебля к дорожке","Направление из цветка в облако","Направление от почвы к корням"],"answer":2,"feedback":["Этот вариант не подходит: «направление от стебля к дорожке». Сравни последствия трёх вариантов.","Этот вариант не подходит: «направление из цветка в облако». Ещё раз посмотри на условие.","Так видно, откуда растение получает воду через корни."]},{"prompt":"Как исправить схему, где ярлык «листья» приклеен к корням?","choices":["Оставить подпись, ведь у растения только одна часть","Нарисовать ещё один камень","Перенести ярлык на зелёные части над землёй"],"answer":2,"feedback":["Этот вариант не подходит: «оставить подпись, ведь у растения только одна часть». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «нарисовать ещё один камень». Сравни последствия трёх вариантов.","Каждую часть следует подписывать отдельно."]},{"prompt":"Что лучше добавить на схему, чтобы показать связь корней и опоры?","choices":["Нарисовать вокруг корня солнечный луч","Покрасить корень как лепесток","Подпись о закреплении в почве"],"answer":2,"feedback":["Этот вариант не подходит: «нарисовать вокруг корня солнечный луч». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «покрасить корень как лепесток». Проверь, относится ли выбор к ситуации.","Корни закрепляют растение в почве."]}],"pass":2},{"id":"world-23","module":"Применение","title":"Соседи на лесной картинке","goal":"Применять группировку живых организмов в общей сцене.","intro":"У одной тропинки могут встречаться очень разные организмы. Один адрес не делает их одной группой.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"К лесным растениям на картинке относятся…","choices":["Паук и подосиновик","Сосна и жук","Сосна и папоротник"],"answer":2,"feedback":["Этот вариант не подходит: «паук и подосиновик». Сравни последствия трёх вариантов.","Этот вариант не подходит: «сосна и жук». Ещё раз посмотри на условие.","Сосна и папоротник относятся к растениям."]},{"prompt":"Кого отметить как животное?","choices":["Дятла","Брусничный куст","Шампиньон на рисунке"],"answer":0,"feedback":["Дятел — птица, а птицы относятся к животным.","Этот вариант не подходит: «брусничный куст». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «шампиньон на рисунке». Сравни последствия трёх вариантов."]},{"prompt":"Дятел, ель и гриб рядом. Как разложить карточки?","choices":["Дятел к животным, ель к растениям, гриб к грибам","Все три к растениям, потому что они в лесу","Все три к животным, потому что вокруг деревья"],"answer":0,"feedback":["Общее место не меняет принадлежность к разным группам.","Этот вариант не подходит: «все три к растениям, потому что они в лесу». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «все три к животным, потому что вокруг деревья». Проверь, относится ли выбор к ситуации."]},{"prompt":"Какое безопасное задание подходит для нарисованной лесной сцены?","choices":["Найти на рисунке представителей трёх групп и назвать их","Собрать неизвестные грибы по картинке и попробовать","Унести домой каждого найденного живого обитателя"],"answer":0,"feedback":["Наблюдать и классифицировать можно без вреда себе и природе.","Этот вариант не подходит: «собрать неизвестные грибы по картинке и попробовать». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «унести домой каждого найденного живого обитателя». Ещё раз посмотри на условие."]}],"pass":2},{"id":"world-24","module":"Применение","title":"Найди подходящее укрытие","goal":"Объяснять выбор места для разных животных.","intro":"Наблюдаем на схемах. Укрытие помогает спрятаться или отдохнуть, но одному виду подходят не все места.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Какой объект может служить укрытием для маленькой рыбы на рисунке?","choices":["Верхушка сухой сосны","Заросли водных растений","Скамейка у дорожки"],"answer":1,"feedback":["Этот вариант не подходит: «верхушка сухой сосны». Сравни последствия трёх вариантов.","Под водой рыба может спрятаться среди растений.","Этот вариант не подходит: «скамейка у дорожки». Найди объяснение, которое подходит к рисунку."]},{"prompt":"На рисунке птица спряталась среди листьев. Что здесь помогает укрытию?","choices":["Густая листва закрывает птицу от взгляда","Листья превращают птицу в цветок","Ветви становятся плавниками"],"answer":0,"feedback":["Густая крона может закрывать птицу.","Этот вариант не подходит: «листья превращают птицу в цветок». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «ветви становятся плавниками». Проверь, относится ли выбор к ситуации."]},{"prompt":"Как сравнить два возможных укрытия ежа?","choices":["Отметить, укрывает ли каждое животное от открытого пространства","Считать любое место одинаковым для всех","Выбрать только по любимому цвету ребёнка"],"answer":0,"feedback":["Укрытие должно соответствовать размерам и образу жизни животного.","Этот вариант не подходит: «считать любое место одинаковым для всех». Ещё раз посмотри на условие.","Этот вариант не подходит: «выбрать только по любимому цвету ребёнка». Проверь, относится ли выбор к ситуации."]},{"prompt":"Ребёнок заметил гнездо и хочет узнать, кто там. Что выбрать?","choices":["Наблюдать издалека со взрослым, не трогая гнездо","Отнести гнездо на солнце ради фото","Раскрыть гнездо палкой"],"answer":0,"feedback":["Спокойное наблюдение не беспокоит животных.","Этот вариант не подходит: «отнести гнездо на солнце ради фото». Ещё раз посмотри на условие.","Этот вариант не подходит: «раскрыть гнездо палкой». Сравни последствия трёх вариантов."]}],"pass":2},{"id":"world-25","module":"Применение","title":"Запланируй заботу о себе","goal":"Переносить знакомые привычки на вымышленные школьные ситуации.","intro":"Полезная привычка должна подходить моменту и быть выполнимой.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"В плане дня после прогулки стоит обед. Какой шаг добавить между ними?","choices":["Вымыть руки","Спрятать тарелки","Рисовать до полуночи"],"answer":0,"feedback":["Мытьё рук уместно перед едой и после улицы.","Этот вариант не подходит: «спрятать тарелки». Проверь, относится ли выбор к ситуации.","Этот вариант не подходит: «рисовать до полуночи». Найди объяснение, которое подходит к рисунку."]},{"prompt":"Что выбрать, если условный день перегружен делами?","choices":["Больше не делать перерывов","Обсудить со взрослым время отдыха","Отказаться от любого движения"],"answer":1,"feedback":["Этот вариант не подходит: «больше не делать перерывов». Проверь, относится ли выбор к ситуации.","Посильный режим включает отдых.","Этот вариант не подходит: «отказаться от любого движения». Ещё раз посмотри на условие."]},{"prompt":"Друг предлагает идти дальше, но у вымышленного героя сильно кружится голова. Что выбрать?","choices":["Сказать взрослому и попросить помочь","Скрыть это и бегать быстрее","Самостоятельно взять неизвестную таблетку"],"answer":0,"feedback":["С плохим самочувствием важно обратиться к доверенному взрослому.","Этот вариант не подходит: «скрыть это и бегать быстрее». Ещё раз посмотри на условие.","Этот вариант не подходит: «самостоятельно взять неизвестную таблетку». Сравни последствия трёх вариантов."]},{"prompt":"Что считать разнообразием в условном меню?","choices":["Разные подходящие продукты, а не несколько видов конфет","Только напитки вместо еды","Каждый день один и тот же десерт"],"answer":0,"feedback":["Разные продукты дают разнообразие; сладости не заменяют обычную еду.","Этот вариант не подходит: «только напитки вместо еды». Сравни последствия трёх вариантов.","Этот вариант не подходит: «каждый день один и тот же десерт». Найди объяснение, которое подходит к рисунку."]}],"pass":2},{"id":"world-26","module":"Применение","title":"Общая комната, разные планы","goal":"Находить договорённость, сохраняя право на отдых и внимание к другим.","intro":"Работаем с вымышленной семьёй. Слова помогают решить спор без наказаний и раскрытия личных дел.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Два ребёнка хотят рисовать на одном столе. Что предложить?","choices":["Убрать чужие рисунки без спроса","Разделить место или договориться о времени","Назначить виноватого до разговора"],"answer":1,"feedback":["Этот вариант не подходит: «убрать чужие рисунки без спроса». Проверь, относится ли выбор к ситуации.","Решение учитывает планы обоих детей.","Этот вариант не подходит: «назначить виноватого до разговора». Ещё раз посмотри на условие."]},{"prompt":"Как может ребёнок сообщить, что ему нужно отдохнуть?","choices":["Толкнуть того, кто попросил помочь","Делать вид, что никого не слышит","Спокойно сказать об усталости и обсудить помощь"],"answer":2,"feedback":["Этот вариант не подходит: «толкнуть того, кто попросил помочь». Ещё раз посмотри на условие.","Этот вариант не подходит: «делать вид, что никого не слышит». Сравни последствия трёх вариантов.","Можно назвать своё состояние и договориться."]},{"prompt":"Персонажу предлагают выполнить опасное для него поручение. Что делать?","choices":["Передать поручение ребёнку помладше","Делать молча, чтобы никто не расстроился","Сказать «не могу безопасно» и обратиться к взрослому"],"answer":2,"feedback":["Этот вариант не подходит: «передать поручение ребёнку помладше». Найди объяснение, которое подходит к рисунку.","Этот вариант не подходит: «делать молча, чтобы никто не расстроился». Сравни последствия трёх вариантов.","Помощь должна быть посильной и безопасной."]},{"prompt":"Что стало бы примером честного распределения простых дел?","choices":["Все дела всегда делает один человек","Каждый выбирает посильное дело в согласованном порядке","Кто выглядит младше, тот всегда виноват"],"answer":1,"feedback":["Этот вариант не подходит: «все дела всегда делает один человек». Найди объяснение, которое подходит к рисунку.","Разговор и посильные задачи учитывают возможности каждого.","Этот вариант не подходит: «кто выглядит младше, тот всегда виноват». Проверь, относится ли выбор к ситуации."]}],"pass":2},{"id":"world-27","module":"Применение","title":"Проведи вещь от мастера до дома","goal":"Объяснять вклад производства, перевозки и продажи на новом примере.","intro":"Условная схема показывает путь изделия, а не конкретный адрес или магазин семьи.","source":"Дополнительная практика, «Топоух».","steps":[{"prompt":"Какой шаг раньше остальных для школьного пенала?","choices":["Упаковать уже сшитый пенал","Подготовить материалы","Разложить готовые пеналы на полке"],"answer":1,"feedback":["Этот вариант не подходит: «упаковать уже сшитый пенал». Сравни последствия трёх вариантов.","Материал нужен прежде, чем вещь можно изготовить.","Этот вариант не подходит: «разложить готовые пеналы на полке». Ещё раз посмотри на условие."]},{"prompt":"Кто в условной цепочке перемещает готовый товар со склада?","choices":["Работник доставки","Писатель сказки","Покупатель, который ещё не пришёл"],"answer":0,"feedback":["Доставка связывает склад и место продажи.","Этот вариант не подходит: «писатель сказки». Сравни последствия трёх вариантов.","Этот вариант не подходит: «покупатель, который ещё не пришёл». Найди объяснение, которое подходит к рисунку."]},{"prompt":"На схеме сначала нарисован магазин, потом швейная мастерская. Что исправить?","choices":["Удалить изготовление: вещь появилась в магазине","Поставить изготовление перед продажей готового изделия","Поставить продажу перед материалами"],"answer":1,"feedback":["Этот вариант не подходит: «удалить изготовление: вещь появилась в магазине». Найди объяснение, которое подходит к рисунку.","Готовое изделие должно появиться раньше продажи.","Этот вариант не подходит: «поставить продажу перед материалами». Проверь, относится ли выбор к ситуации."]},{"prompt":"Если нет одного вида материала, какое решение в схеме разумно?","choices":["Пропустить этап подготовки материалов","Объявить, что любого материала достаточно","Спросить у мастера о подходящей замене"],"answer":2,"feedback":["Этот вариант не подходит: «пропустить этап подготовки материалов». Ещё раз посмотри на условие.","Этот вариант не подходит: «объявить, что любого материала достаточно». Проверь, относится ли выбор к ситуации.","Мастер учитывает, какие материалы подходят для изделия."]}],"pass":2}]});
